<template><div><div class="page-heading"><div><h1>营业概览</h1><p>查看当日预约、实收和商品排行。</p></div><el-button icon="el-icon-refresh" @click="load" :loading="loading">刷新数据</el-button></div><div class="metric-grid"><article><span>今日实收</span><strong>¥ {{ money(data.revenue||0) }}</strong><p>已收款且未取消</p></article><article><span>今日预约</span><strong>{{ data.todayOrders||0 }}<small>单</small></strong></article><article><span>待确认预约</span><strong>{{ data.pending||0 }}<small>单</small></strong></article><article><span>正在备货</span><strong>{{ data.confirmed||0 }}<small>单</small></strong></article></div><section class="atelier-panel overview-panel"><div class="panel-toolbar"><div><h2>今日商品热度</h2><p>按今天未取消订单的实际件数统计</p></div></div><div v-loading="loading" class="ranking"><article v-for="(p,i) in data.ranking||[]" :key="p.id"><span class="ranking-index">{{ String(i+1).padStart(2,'0') }}</span><img :src="p.image" :alt="p.name"><strong>{{ p.name }}</strong><el-progress :percentage="percentage(p.sold)" :show-text="false" color="#ac9871"></el-progress><span>{{ p.sold }} 件</span></article></div></section></div></template>
<script>
import {loadDashboard} from '@/api/catalog'
import {money} from '@/utils/money'
export default{data:()=>({data:{},loading:true}),mounted(){this.load()},methods:{money,percentage(n){const max=Math.max(1,...(this.data.ranking||[]).map(r=>r.sold));return Math.floor(n/max*100)},async load(){this.loading=true;try{this.data=await loadDashboard()}catch(e){this.$message.error(e.message)}finally{this.loading=false}}}}
</script>
